WITH parsed AS (SELECT id, currency, tier_limits, discounts, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT id, currency, entry_price, MIN(entry_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_entry_price, MAX(entry_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_entry_price, COUNT(entry_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_entry_price, AVG(entry_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_entry_price FROM parsed;
